:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #172321;
  color: #f4f0df;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(ellipse at 50% 10%, #30443b 0, #172321 65%);
}

.board {
  width: min(100%, 540px);
  padding: clamp(24px, 6vw, 42px);
  border: 1px solid #526557;
  border-radius: 18px;
  background: #202e29;
  box-shadow: 0 20px 60px #0b1210aa;
}

.heading { display: flex; align-items: center; gap: 16px; }
.pixel-mark {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 2px solid #d1a95b;
  border-radius: 10px;
  color: #e6c579;
  font-size: 32px;
  line-height: 1;
}
.eyebrow { margin: 0 0 4px; color: #c4a861; font-size: 0.78rem; font-weight: 750; letter-spacing: 0.13em; }
h1 { margin: 0; font-size: clamp(1.35rem, 5vw, 1.8rem); line-height: 1.2; }
.hint { margin: 28px 0 14px; color: #c2cec2; }

.clocks { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.clock {
  min-width: 0;
  min-height: 180px;
  padding: 18px 12px;
  border: 2px solid #526557;
  border-radius: 12px;
  background: #293a32;
  color: #f4f0df;
  cursor: pointer;
  text-align: center;
  transition: background 120ms ease, border-color 120ms ease, transform 120ms ease;
}
.clock:hover { border-color: #d1a95b; background: #33473d; }
.clock:active { transform: translateY(2px); }
.clock:focus-visible, .pause-button:focus-visible { outline: 3px solid #e6c579; outline-offset: 4px; }
.clock.active { border-color: #e0bb69; background: #3a4935; box-shadow: inset 0 0 0 1px #e0bb6944; }
.clock[disabled] { cursor: default; opacity: 0.76; }
.player { display: flex; align-items: center; justify-content: center; gap: 7px; font-size: 1rem; font-weight: 700; }
.piece { font-size: 1.3rem; }
.white-piece { color: #fff8dc; text-shadow: 0 1px 2px #111; }
.black-piece { color: #d1a95b; }
.time { display: block; margin: 20px 0 12px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: clamp(2.1rem, 10vw, 3rem); font-weight: 750; font-variant-numeric: tabular-nums; line-height: 1; }
.clock-status { color: #aab8a9; font-size: 0.75rem; font-weight: 750; letter-spacing: 0.12em; }
.clock.active .clock-status { color: #e6c579; }

.flag { margin: 18px 0 0; color: #ffbd78; font-size: 1.4rem; font-weight: 800; text-align: center; }
[hidden] { display: none !important; }
.pause-button {
  width: 100%;
  min-height: 52px;
  margin-top: 20px;
  border: 1px solid #d1a95b;
  border-radius: 9px;
  background: #d1a95b;
  color: #172321;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: background 120ms ease, transform 120ms ease;
}
.pause-button:hover { background: #e6c579; }
.pause-button:active { transform: translateY(2px); }
.pause-button[disabled] { cursor: default; opacity: 0.55; }
.footer-note { margin: 18px 0 0; color: #aab8a9; font-size: 0.9rem; text-align: center; }
.footer-note span { padding: 0 5px; color: #d1a95b; }

@media (max-width: 400px) {
  .clocks { gap: 8px; }
  .clock { min-height: 165px; padding-inline: 8px; }
}

const START_SECONDS = 5 * 60;
const remaining = [START_SECONDS, START_SECONDS];
const clockButtons = [document.getElementById('white-clock'), document.getElementById('black-clock')];
const timeLabels = [document.getElementById('white-time'), document.getElementById('black-time')];
const statusLabels = [document.getElementById('white-status'), document.getElementById('black-status')];
const pauseButton = document.getElementById('pause-button');
const flagMessage = document.getElementById('flag-message');
let activePlayer = 0;
let paused = false;
let flagged = false;
let previousTick = Date.now();

function formatTime(seconds) {
  const wholeSeconds = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(wholeSeconds / 60)}:${String(wholeSeconds % 60).padStart(2, '0')}`;
}

function render() {
  remaining.forEach((seconds, index) => {
    timeLabels[index].textContent = formatTime(seconds);
    clockButtons[index].setAttribute('aria-label', `${index === 0 ? 'White' : 'Black'} clock, ${formatTime(seconds)} remaining. Tap to switch turns.`);
    clockButtons[index].setAttribute('aria-pressed', String(!paused && !flagged && activePlayer === index));
    clockButtons[index].classList.toggle('active', !paused && !flagged && activePlayer === index);
    statusLabels[index].textContent = seconds <= 0 ? 'FLAGGED' : paused ? 'PAUSED' : flagged ? 'FINISHED' : activePlayer === index ? 'YOUR TURN' : 'WAITING';
    clockButtons[index].disabled = paused || flagged || seconds <= 0;
  });
  pauseButton.textContent = paused ? 'Resume' : 'Pause';
  pauseButton.setAttribute('aria-pressed', String(paused));
  pauseButton.disabled = flagged;
}

function tick() {
  const now = Date.now();
  if (!paused && !flagged) {
    remaining[activePlayer] = Math.max(0, remaining[activePlayer] - (now - previousTick) / 1000);
    if (remaining[activePlayer] <= 0) {
      flagged = true;
      flagMessage.hidden = false;
    }
    render();
  }
  previousTick = now;
}

clockButtons.forEach((button, index) => {
  button.addEventListener('click', () => {
    if (paused || flagged || index !== activePlayer) return;
    tick();
    if (!flagged) {
      activePlayer = 1 - activePlayer;
      previousTick = Date.now();
      render();
    }
  });
});

pauseButton.addEventListener('click', () => {
  if (flagged) return;
  tick();
  if (!flagged) {
    paused = !paused;
    previousTick = Date.now();
    render();
  }
});

render();
window.setInterval(tick, 100);
